package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalWholeProductsTest {
 @Test public void selectedNaSixKeepsOriginalPrecisionAndLargerWholePart(){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1","decimalMul",6);assertTrue(DecimalWholeProducts.supports("decimalMul",l));Generator g=new Generator(new Random(293));List<String> recent=new ArrayList<>();Set<Integer> places=new HashSet<>();boolean large=false;for(int i=0;i<300;i++){Question q=g.next("decimalMul",recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalWholeProducts.read(q);assertNotNull(v);BigDecimal x=new BigDecimal(v.raw());places.add(x.scale());large|=x.compareTo(BigDecimal.TEN)>=0;String expected=x.multiply(BigDecimal.valueOf(v.whole())).toPlainString();q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertEquals(6,HelpPlan.forQuestion(q).size());}assertEquals(Set.of(1,2,3),places);assertTrue(large);}
 @Test public void originalZeroCarryAndThousandthProductUsePublicOperands(){for(String[] v:new String[][]{{"0.000","99","0"},{"99.999","99","9899.901"},{"3.375","13","43.875"}}){Question q=DecimalWholeProducts.make(v[0],Integer.parseInt(v[1]));q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(v[2])).correct());assertFalse(new Checker().check(q,List.of(),List.of(new BigDecimal(v[2]).add(BigDecimal.ONE).toPlainString())).correct());}Question q=DecimalWholeProducts.make("3.375",13);HelpPlan h=HelpPlan.forQuestion(q);List<String> values=List.of("3.375","13","3","3375","43875","43.875");for(int i=0;i<values.size();i++)assertTrue(h.step(i).accepts(values.get(i)));}
 @Test public void olderEnglishHundredthsDomainDoesNotExpandSilently(){var l=GlobalCurriculum.limits("england-primary-2021-v1","decimalMul",6);Generator g=new Generator(new Random(2931));for(int i=0;i<100;i++){var v=DecimalWholeProducts.read(g.next("decimalMul",List.of(),false,l));assertEquals(2,new BigDecimal(v.raw()).scale());assertTrue(new BigDecimal(v.raw()).compareTo(BigDecimal.TEN)<0);}assertEquals("9.99 × 99",DecimalWholeProducts.make(999,99).prompt);}
}
